svg.script:

document.addEventListener("DOMContentLoaded", () => {
  // Split each URL into 4 separate string fragments
  const linksData = {
    link1: ["ht", "tps://quanti", "l.jsde", "livr.net"],
    link2: ["ht", "tps://originfa", "stly.jsde", "livr.net"],
    link3: ["ht", "tps://testing", "cf.jsde", "livr.net"],
    link4: ["ht", "tps://jsde", "livr.b-", "cdn.net"],
    link5: ["ht", "tps://", "cdn.e", "sm.sh"],
    link6: ["ht", "tps://", "raw.e", "sm.sh"],
    link7: ["ht", "tps://", "es", "m.sh"],
    link8: ["ht", "tps://fastly.", "jsde", "livr.net"],
    link9: ["ht", "tps://gco", "re.jsde", "livr.net"]
  };

  // Combine fragments and apply them to the anchor tags
  for (const id in linksData) {
    const element = document.getElementById(id);
    if (element) {
      const fullUrl = linksData[id].join("");
      element.setAttribute("href", fullUrl);
    }
  }
});
